query IssueByNumber($owner: String!, $repo: String!, $number: Int!) {
	repository(owner: $owner, name: $repo) {
		hasIssuesEnabled
		issue: issueOrPullRequest(number: $number) {
			__typename
			...on Issue{number,title,body,state,labels(first:100){nodes{id,name,description,color},totalCount},comments(first: 100) {nodes {id,author{login,...on User{id,name}},authorAssociation,body,createdAt,includesCreatedEdit,isMinimized,minimizedReason,reactionGroups{content,users{totalCount}},url,viewerDidAuthor},pageInfo{hasNextPage,endCursor},totalCount},id}
			...on PullRequest{number,title,body,state,labels(first:100){nodes{id,name,description,color},totalCount},comments(first: 100) {nodes {id,author{login,...on User{id,name}},authorAssociation,body,createdAt,includesCreatedEdit,isMinimized,minimizedReason,reactionGroups{content,users{totalCount}},url,viewerDidAuthor},pageInfo{hasNextPage,endCursor},totalCount},id}
		}
	}
}
